        <div className="flex-1 min-w-0">
          <h4 className="font-semibold text-slate-300">{label}:</h4>
          {isSummary ? (
            <p className="text-slate-200 text-sm leading-relaxed break-words whitespace-pre-wrap">
              {displayValue}
