      <div className="bg-slate-900 p-4 sm:p-6 rounded-lg shadow-inner border border-slate-700/50">
        {renderDetailItem(BookText, "Summary", summary, true)}
        {renderDetailItem(Clock, "Audio Length", audioDuration)}
